// DEV_RIO_601 Lead Gen【LINE通知・下書き準備】
// ウェビナー登録者からのリード獲得フロー。LINE Messaging APIで通知。
// ドライラン：通知下書きのみ生成。自動送信はしない。
const i = $input.first().json;
return [{ json: {
  lead_id: i.lead_id ?? 'lead-' + Date.now(),
  webinar_id: i.webinar_id ?? 'wf-001',
  email: i.email ?? 'test@example.com',
  name: i.name ?? 'テストリード',
  status: i.status ?? 'new',
  line_user_id: i.line_user_id ?? 'U' + Math.random().toString(36).substr(2, 9),
  platform: 'line',
  action_type: 'send_lead_notification'
} }];

// LINE通知メッセージを組み立てる（Claude生成）
const i = $input.first().json;
const prompt = `以下のリード情報から、LINE通知の下書きメッセージを作成してください。

リード名: ${i.name}
メール: ${i.email}
ウェビナーID: ${i.webinar_id}

条件:
- 100字以内、日本語
- リード獲得の感謝メッセージ
- 次のアクション（フォローアップ予定など）を示唆
- 出力は次のJSON配列のみ: [{"message":"string","next_action":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。LINE通知下書きを停止前に生成（公開しない）
const input = $input.first().json;
const ctx = $('Collect Lead Input').first().json;
let messages = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    messages = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(messages) || messages.length === 0) throw new Error('messages missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) messages = [{ message: '（AI応答の取得/解析に失敗。手動で通知を作成してください）', next_action: 'manual' }];
return [{ json: {
  lead_id: ctx.lead_id,
  line_user_id: ctx.line_user_id,
  line_messages: messages,
  message_count: messages.length,
  state: 'READY_FOR_REVIEW',
  draft_only: true,
  parse_error: parse_error,
  note: 'ドライラン。LINE通知下書きのみ生成。自動送信はしない。人間が確認後、手動で LINE Messaging API を実行する。'
} }];
